Plan:
- Read the cached values from `Emp` and `Lookup`, mapping employee key columns and variable-to-category/subcategory lookups.
- For each employee row, emit one output row for each variable column from `Comp1` through `performance`, repeating the key columns and adding the matched category/subcategory and value.
- Clear and fill the answer region `Expected!A2:H19` with plain values, limited to the 18 available answer rows.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

if "Expected" not in wb.sheetnames:
    wb.create_sheet("Expected")

ws = wb["Expected"]
emp = vals["Emp"]
lookup = vals["Lookup"]

def norm(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return v
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v

# Map Emp headers
header = {}
header_ci = {}
for c in range(1, emp.max_column + 1):
    h = norm(emp.cell(1, c).value)
    if h is not None:
        header[h] = c
        header_ci[str(h).lower()] = c

# Map Lookup variables to category/subcategory
lookup_map = {}
lookup_map_ci = {}
lookup_vars = []
for r in range(2, lookup.max_row + 1):
    var = norm(lookup.cell(r, 1).value)
    if var is None:
        continue
    cat = norm(lookup.cell(r, 2).value)
    sub = norm(lookup.cell(r, 3).value)
    lookup_map[var] = (cat, sub)
    lookup_map_ci[str(var).lower()] = (cat, sub)
    lookup_vars.append(var)

def get_lookup(var):
    if var is None:
        return (None, None)
    if var in lookup_map:
        return lookup_map[var]
    return lookup_map_ci.get(str(var).lower(), (None, None))

# Key columns to repeat for each transposed variable
key_names = ["seqno", "Empno", "ename", "Jobid"]
key_cols = [header_ci.get(n.lower()) for n in key_names]
if any(c is None for c in key_cols):
    key_cols = [1, 2, 3, 4]

# Variable columns: Emp range Comp1 through performance
start = header_ci.get("comp1")
end = header_ci.get("performance")
if start is not None and end is not None and start <= end:
    var_cols = []
    for c in range(start, end + 1):
        h = norm(emp.cell(1, c).value)
        if h is not None:
            var_cols.append((c, h))
else:
    var_cols = []
    for var in lookup_vars:
        c = header.get(var)
        if c is not None:
            var_cols.append((c, var))

# Clear answer region
for r in range(2, 20):
    for c in range(1, 9):
        ws.cell(r, c).value = None

filled = 0
for r in range(2, emp.max_row + 1):
    if all(emp.cell(r, c).value is None for c in key_cols):
        continue

    keys = [norm(emp.cell(r, c).value) for c in key_cols]

    for c, var in var_cols:
        if filled >= 18:
            break

        val = norm(emp.cell(r, c).value)
        cat, sub = get_lookup(var)
        out_r = 2 + filled

        ws.cell(out_r, 1).value = keys[0]
        ws.cell(out_r, 2).value = keys[1]
        ws.cell(out_r, 3).value = keys[2]
        ws.cell(out_r, 4).value = keys[3]
        ws.cell(out_r, 5).value = var
        ws.cell(out_r, 6).value = cat
        ws.cell(out_r, 7).value = sub
        ws.cell(out_r, 8).value = val

        filled += 1

    if filled >= 18:
        break

wb.save(OUT)

print("filled rows:", filled)
print("row2:", [ws.cell(2, c).value for c in range(1, 9)])
print("row19:", [ws.cell(19, c).value for c in range(1, 9)])
```

